package dev.thillainirmal.deeprag;
import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api")
public class RagController{private final RagLab lab;public RagController(RagLab l){lab=l;}@PostMapping("/run")public RagLab.Result run(@Valid @RequestBody Query q){return lab.run(q.query(),q.domain());}@PostMapping("/documents")@ResponseStatus(HttpStatus.CREATED)public RagLab.Doc add(@Valid @RequestBody Document d){return lab.add(d.title(),d.domain(),d.text());}@GetMapping("/documents")public List<RagLab.Doc> documents(){return lab.documents();}@PostMapping("/evaluate")public RagLab.Evaluation evaluate(@Valid @RequestBody EvaluationRequest e){return lab.evaluate(e.query(),e.domain(),e.expectedDocumentIds());}public record Query(@NotBlank @Size(max=2000)String query,@NotBlank @Size(max=80)String domain){}public record Document(@NotBlank @Size(max=160)String title,@NotBlank @Size(max=80)String domain,@NotBlank @Size(max=50000)String text){}public record EvaluationRequest(@NotBlank String query,@NotBlank String domain,@NotEmpty Set<String> expectedDocumentIds){} }
